from pathlib import Path

p=Path('app/src/main/assets/index.html')
s=p.read_text(encoding='utf-8')
if 'tus-js-client@4.3.1' not in s:
    s=s.replace('<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script>','<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script><script src="https://cdn.jsdelivr.net/npm/tus-js-client@4.3.1/dist/tus.min.js"></script>',1)

css='''<style id="asia-cms-overlay-css">#asiaAdminCMS{display:none;position:relative;z-index:20;padding-bottom:110px}#asiaAdminCMS.on{display:block}.cmsWrap{padding:0 15px}.cmsTabs{display:flex;gap:7px;overflow:auto;margin-bottom:10px}.cmsTabs button{flex:0 0 auto}.cmsPane{display:none}.cmsPane.on{display:block}.cmsCard{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:14px;margin-bottom:10px}.cmsCard h3{margin:0 0 10px;font-size:18px}.cmsGrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.cmsList{display:grid;gap:8px}.cmsItem{padding:12px;border:1px solid var(--line);border-radius:14px;background:#111217}.cmsMeta{font-size:12px;color:var(--muted);margin-top:4px}.cmsProgress{height:7px;background:#282a31;border-radius:99px;overflow:hidden;margin:8px 0}.cmsProgress i{display:block;height:100%;width:0;background:var(--red)}@media(max-width:520px){.cmsGrid{grid-template-columns:1fr}}#admin.hidden{display:none!important}</style>'''
s=s.replace('</head>',css+'</head>',1)

markup='''<section id="asiaAdminCMS"><div class="head"><h2>Creator Studio</h2><button class="link" type="button" onclick="cmsRefresh()">Refresh</button></div><div class="cmsWrap"><div class="cmsTabs"><button class="tab on" type="button" onclick="cmsPane('library',this)">Library</button><button class="tab" type="button" onclick="cmsPane('series',this)">New Series</button><button class="tab" type="button" onclick="cmsPane('episode',this)">Upload Episode</button></div><div id="cmsLibrary" class="cmsPane on"><div class="cmsCard"><b>Your content</b><div class="cmsMeta">Drafts are private. Published videos appear in the public catalogue.</div></div><div id="cmsList" class="cmsList"></div></div><div id="cmsSeries" class="cmsPane"><div class="cmsCard"><h3>Create a series</h3><input id="cmsTitle" class="field" placeholder="Series title"><textarea id="cmsDesc" class="field area" placeholder="Description"></textarea><div class="cmsGrid"><input id="cmsGenre" class="field" placeholder="Genre"><input id="cmsLang" class="field" placeholder="Language"></div><input id="cmsAge" class="field" placeholder="Age rating"><label class="small">Poster</label><input id="cmsPoster" class="field" type="file" accept="image/jpeg,image/png,image/webp,image/avif"><label class="small">Banner (optional)</label><input id="cmsBanner" class="field" type="file" accept="image/jpeg,image/png,image/webp,image/avif"><label class="setting"><span>Publish now</span><input id="cmsSeriesPublish" type="checkbox" checked></label><button class="primary" type="button" onclick="cmsCreateSeries()">Create series</button><div id="cmsSeriesMsg" class="small"></div></div></div><div id="cmsEpisode" class="cmsPane"><div class="cmsCard"><h3>Upload episode</h3><select id="cmsSeriesSelect" class="field"></select><div class="cmsGrid"><input id="cmsSeason" class="field" type="number" min="1" value="1" placeholder="Season"><input id="cmsEpisodeNo" class="field" type="number" min="1" value="1" placeholder="Episode"></div><input id="cmsSeasonTitle" class="field" placeholder="Season title (optional)"><input id="cmsEpisodeTitle" class="field" placeholder="Episode title"><textarea id="cmsEpisodeDesc" class="field area" placeholder="Episode description"></textarea><label class="small">Thumbnail</label><input id="cmsThumb" class="field" type="file" accept="image/jpeg,image/png,image/webp,image/avif"><label class="small">Video</label><input id="cmsVideo" class="field" type="file" accept="video/mp4,video/webm,video/quicktime"><div class="cmsGrid"><select id="cmsAccess" class="field"><option value="free">Free</option><option value="paid">Paid</option></select><input id="cmsPrice" class="field" type="number" min="0" step="1" value="0" placeholder="Price INR"></div><input id="cmsPlayProduct" class="field" placeholder="Google Play product ID for paid content"><label class="setting"><span>Publish now</span><input id="cmsEpisodePublish" type="checkbox" checked></label><div id="cmsUploadMsg" class="small"></div><div class="cmsProgress"><i id="cmsProgressBar"></i></div><button class="primary" type="button" onclick="cmsCreateEpisode()">Upload & publish</button></div></div></div></section>'''
s=s.replace('</body>',markup+'</body>',1)

js=r'''<script id="asia-cms-overlay-runtime">
(function(){
const MEDIA='asia-media',POSTERS='asia-posters',HOST='https://wevutronudkcqbzmverf.storage.supabase.co',PLAY=API+'/playback-url';
const el=id=>document.getElementById(id),msg=(id,v)=>{const e=el(id);if(e)e.textContent=v||''},safeVal=v=>typeof safe==='function'?safe(v):String(v||'');
async function sess(){return (await supabase.auth.getSession()).data.session}
async function isAdmin(){if(!user)return false;const r=await supabase.from('admin_roles').select('role').eq('user_id',user.id).limit(1).maybeSingle();return !!r.data}
async function poster(file){if(!file)return '';const path='admin/'+user.id+'/'+Date.now()+'-'+file.name.replace(/[^a-zA-Z0-9._-]/g,'-');const r=await supabase.storage.from(POSTERS).upload(path,file,{contentType:file.type||'image/jpeg',cacheControl:'31536000'});if(r.error)throw r.error;return supabase.storage.from(POSTERS).getPublicUrl(path).data.publicUrl}
async function video(file){const s=await sess();if(!s)throw Error('Please sign in again.');const path='admin/'+user.id+'/'+Date.now()+'-'+file.name.replace(/[^a-zA-Z0-9._-]/g,'-');const bar=el('cmsProgressBar');const set=p=>{if(bar)bar.style.width=Math.max(0,Math.min(100,p))+'%';msg('cmsUploadMsg','Uploading video • '+Math.floor(p)+'%')};if(file.size<=6*1024*1024){const r=await supabase.storage.from(MEDIA).upload(path,file,{contentType:file.type||'video/mp4',cacheControl:'31536000'});if(r.error)throw r.error;set(100);return 'storage://'+MEDIA+'/'+path}if(!window.tus)throw Error('Large-video uploader unavailable.');await new Promise((resolve,reject)=>{const u=new tus.Upload(file,{endpoint:HOST+'/storage/v1/upload/resumable',retryDelays:[0,3000,5000,10000,20000],headers:{authorization:'Bearer '+s.access_token,'x-upsert':'false'},uploadDataDuringCreation:true,removeFingerprintOnSuccess:true,metadata:{bucketName:MEDIA,objectName:path,contentType:file.type||'video/mp4',cacheControl:'31536000'},chunkSize:6*1024*1024,onProgress:(a,b)=>set(b?a/b*100:0),onError:reject,onSuccess:resolve});u.findPreviousUploads().then(x=>{if(x.length)u.resumeFromPreviousUpload(x[0]);u.start()}).catch(reject)});set(100);return 'storage://'+MEDIA+'/'+path}
window.cmsPane=function(name,b){document.querySelectorAll('#asiaAdminCMS .cmsPane').forEach(x=>x.classList.remove('on'));el('cms'+name.charAt(0).toUpperCase()+name.slice(1))?.classList.add('on');document.querySelectorAll('#asiaAdminCMS .cmsTabs button').forEach(x=>x.classList.remove('on'));b?.classList.add('on');if(name==='episode')cmsSeriesOptions()};
async function cmsSeriesOptions(){const s=el('cmsSeriesSelect');if(!s)return;const r=await supabase.from('series').select('id,title').order('created_at',{ascending:false});s.innerHTML=(r.data||[]).map(x=>'<option value="'+safeVal(x.id)+'">'+safeVal(x.title)+'</option>').join('')||'<option value="">Create a series first</option>'}
window.cmsCreateSeries=async function(){try{if(!(await isAdmin()))throw Error('Admin access required.');const title=el('cmsTitle').value.trim();if(!title)throw Error('Enter a series title.');const posterUrl=await poster(el('cmsPoster').files[0]);const bannerUrl=await poster(el('cmsBanner').files[0]);const r=await supabase.from('series').insert({title,description:el('cmsDesc').value.trim()||null,genre:el('cmsGenre').value.trim()||null,language:el('cmsLang').value.trim()||null,age_rating:el('cmsAge').value.trim()||null,poster_url:posterUrl||null,banner_url:bannerUrl||null,status:el('cmsSeriesPublish').checked?'published':'draft',created_by:user.id}).select('id').single();if(r.error)throw r.error;msg('cmsSeriesMsg','Series created.');toast('Series created');await loadCatalog();await cmsRefresh();cmsPane('episode',document.querySelectorAll('#asiaAdminCMS .cmsTabs button')[2])}catch(e){msg('cmsSeriesMsg',e.message);toast(e.message)}};
window.cmsCreateEpisode=async function(){try{if(!(await isAdmin()))throw Error('Admin access required.');const sid=el('cmsSeriesSelect').value,file=el('cmsVideo').files[0],title=el('cmsEpisodeTitle').value.trim();if(!sid)throw Error('Create a series first.');if(!file)throw Error('Select a video.');if(!title)throw Error('Enter episode title.');msg('cmsUploadMsg','Creating season…');const sn=Math.max(1,parseInt(el('cmsSeason').value||'1'));const en=Math.max(1,parseInt(el('cmsEpisodeNo').value||'1'));let q=await supabase.from('seasons').select('id').eq('series_id',sid).eq('season_number',sn).maybeSingle();if(q.error)throw q.error;if(!q.data){q=await supabase.from('seasons').insert({series_id:sid,season_number:sn,title:el('cmsSeasonTitle').value.trim()||('Season '+sn)}).select('id').single();if(q.error)throw q.error}const videoUrl=await video(file);const thumbUrl=await poster(el('cmsThumb').files[0]);const access=el('cmsAccess').value;if(access==='paid'&&!el('cmsPlayProduct').value.trim())throw Error('Google Play product ID is required for paid Android content.');const row={season_id:q.data.id,episode_number:en,title,description:el('cmsEpisodeDesc').value.trim()||null,thumbnail_url:thumbUrl||null,video_url:videoUrl,access_type:access,price_paise:Math.max(0,Math.round(Number(el('cmsPrice').value||0)*100)),currency:'INR',status:el('cmsEpisodePublish').checked?'published':'draft',release_at:el('cmsEpisodePublish').checked?new Date().toISOString():null,play_product_id:el('cmsPlayProduct').value.trim()||null,content_type:'episode'};const r=await supabase.from('episodes').insert(row);if(r.error)throw r.error;msg('cmsUploadMsg','Published successfully.');toast('Episode published');await loadCatalog();await cmsRefresh()}catch(e){msg('cmsUploadMsg',e.message);toast(e.message)}};
window.cmsRefresh=async function(){if(!(await isAdmin())){toast('This account is not an admin yet.');return}const r=await supabase.from('series').select('id,title,status,poster_url,genre,language,seasons(id,season_number,episodes(id,episode_number,title,status,access_type))').order('created_at',{ascending:false});const host=el('cmsList');if(r.error){host.innerHTML='<div class="empty">Unable to load library.</div>';return}host.innerHTML=(r.data||[]).map(x=>'<div class="cmsItem"><b>'+safeVal(x.title)+'</b><div class="cmsMeta">'+safeVal(x.status||'draft')+' • '+safeVal(x.genre||'Drama')+' • '+safeVal(x.language||'Asia')+'</div><div class="cmsMeta">'+(x.seasons||[]).flatMap(s=>(s.episodes||[]).map(e=>'S'+s.season_number+' E'+e.episode_number+' • '+e.title+' • '+e.status)).join('<br>')+'</div></div>').join('')||'<div class="empty">No content yet.</div>';await cmsSeriesOptions()};
const oldGo=window.go;window.go=function(id,nav,tab){if(id!=='admin'){el('asiaAdminCMS').classList.remove('on');el('admin')?.classList.remove('hidden');oldGo(id,nav);return}oldGo('admin',nav);el('admin')?.classList.add('hidden');el('asiaAdminCMS').classList.add('on');cmsRefresh()};
const oldPlay=window.playEpisode;window.playEpisode=async function(id,title,url,paid){if(paid){return oldPlay(id,title,url,paid)}const s=await sess();if(!s)return openSheet('auth');try{mediaMessage('Checking playback access…');const r=await fetch(PLAY+'?episode_id='+encodeURIComponent(id),{headers:{Authorization:'Bearer '+s.access_token}});const j=await r.json();if(!r.ok)throw Error(j.error||'Playback unavailable');currentEpisodeId=id;closeSheet();el('playerTitle').textContent=title||j.title||'Asia Drama';const v=el('video');v.pause();v.src=j.url;v.controls=true;v.load();el('player').classList.add('on');v.play().catch(()=>{});mediaMessage('')}catch(e){mediaMessage('');toast(e.message||'Playback unavailable')}};
setTimeout(()=>{isAdmin().then(ok=>{el('adminButton')?.classList.toggle('hidden',!ok)})},500);
})();
</script>'''
s=s.replace('</body>',js+'</body>',1)
p.write_text(s,encoding='utf-8')
print('CMS overlay applied')
